// InventoryServiceServer is the server API for InventoryService service.
// All implementations should embed UnimplementedInventoryServiceServer
// for forward compatibility.
type InventoryServiceServer interface {
	// GetInventory 读玩家背包(货币 + 道具堆叠);客户端可见结构,不下发存储字段。
	GetInventory(context.Context, *GetInventoryRequest) (*GetInventoryResponse, error)
	// GrantItems 幂等发放道具 / 货币(系统驱动:战后掉落 / 活动 / 购买到账)。
	GrantItems(context.Context, *GrantItemsRequest) (*GrantItemsResponse, error)
	// UseItem 大厅态使用消耗品(开箱 / 经验书等);战斗内即时道具走 GAS,不走此 RPC。
	UseItem(context.Context, *UseItemRequest) (*UseItemResponse, error)
	// ConsumeBattleItem 持久扣减已由 UE GAS 局内使用的可堆叠消耗品(系统接口)。
	// 仅接受可信 battle_result 进度出箱；客户端不得直调，也不得用大厅 UseItem 冒充。
	ConsumeBattleItem(context.Context, *ConsumeBattleItemRequest) (*ConsumeBattleItemResponse, error)
	// DiscardBattleItem 持久扣减副本内丢弃的可堆叠道具(系统接口)。装备实例不支持：
	// phase0 DS 本地 Guid 不是 inventory instance_id，实例只能回大厅走 DiscardInstance。
	DiscardBattleItem(context.Context, *DiscardBattleItemRequest) (*DiscardBattleItemResponse, error)
	// SellItem 出售可堆叠道具换货币(原子扣道具 + 加货币)。
	// 单价来自道具表 sell_price;结算币种取服务端配置 `currency.sell_kind`(默认金币)。
	// 刻意**不**给道具表加"出售币种"列:当前没有"卖某道具得钻石"的确认需求,
	// 加列要动策划源表且属预设性复杂化(§15.3);真有需求时再加列,接口不用改。
	SellItem(context.Context, *SellItemRequest) (*SellItemResponse, error)
	// DiscardItem 丢弃可堆叠道具(客户端 RPC,以调用者身份为准)。
	// 幂等键绑定 item_config_id+count；响应丢失重试不会重复扣减。
	DiscardItem(context.Context, *DiscardItemRequest) (*DiscardItemResponse, error)
	// GrantInstances 幂等发放装备实例(系统驱动:掉落 / 活动 / 购买到账)。
	// 每件生成一个雪花 instance_id,默认未鉴定(identified=false,无随机属性);
	// 幂等键防重复入账(同 drop:<match_id> 重放只生效一次)。不在 Envoy 暴露(同 GrantItems)。
	GrantInstances(context.Context, *GrantInstancesRequest) (*GrantInstancesResponse, error)
	// IdentifyItem 鉴定一件未鉴定装备实例:服务端权威 roll 随机属性(反作弊,不变量 §6)后落库。
	// 幂等:instance_id 已鉴定 → 直接回放已有属性(不重复 roll);实例不存在 / 非本人 → 拒。
	// 客户端 RPC:以 Envoy 注入身份为准,不信任请求体 player_id(同 GetInventory)。
	IdentifyItem(context.Context, *IdentifyItemRequest) (*IdentifyItemResponse, error)
	// DiscardInstance 丢弃一件装备实例(从背包永久删除;客户端 RPC,以调用者身份为准)。
	// 幂等:实例不存在(已丢弃)→ OK no-op;非本人持有 → 拒。
	DiscardInstance(context.Context, *DiscardInstanceRequest) (*DiscardInstanceResponse, error)
	// MoveInstance 移动一件装备实例到新格子(改 slot_index;客户端 RPC,以调用者身份为准)。
	// 目标格越界(>= capacity)/ 已被占用 → 拒。纯大厅整理操作,不影响属性。
	MoveInstance(context.Context, *MoveInstanceRequest) (*MoveInstanceResponse, error)
	// SellInstance 出售唯一装备实例换货币(客户端 RPC,以调用者身份为准)。
	// 绑定实例拒绝；删除实例与货币入账、ledger 幂等流水在同一事务。
	SellInstance(context.Context, *SellInstanceRequest) (*SellInstanceResponse, error)
	// GetShop 读某个商店的权威价目表(客户端 RPC;只读,不鉴权到具体玩家资产)。
	// 客户端用它渲染商品列表与单价——展示口径与扣费口径因此同源,不会漂移(§17.3)。
	// 商店不存在 / 未配置 → ERR_INVALID_ARG,客户端据此隐藏商店页签。
	GetShop(context.Context, *GetShopRequest) (*GetShopResponse, error)
	// PurchaseShopItem 向 NPC 商店购买道具(客户端 RPC,以调用者身份为准)。
	//
	// 服务端权威链:读商店表定价 → 校验该商店确实在售该道具 → 溢出安全算总价 →
	// 同一 MySQL 本地事务里【扣货币 + 入包(堆叠计数或生成装备实例) + 写 ledger 幂等流水】。
	// 客户端传来的任何价格都不被信任;count 只是"买几份",单价与每份数量以表为准。
	//
	// 幂等键 = idempotency_key(客户端生成,绑定 shop_id+item_config_id+count 指纹):
	// 响应丢失重试不会重复扣费、不会重复入包(§9.7)。
	// 余额不足 → ERR_INVENTORY_INSUFFICIENT;不在售 → ERR_INVENTORY_NOT_PURCHASABLE;
	// 装备实例背包满 → ERR_INVENTORY_CAPACITY_FULL(此时整笔回滚,不扣钱)。
	PurchaseShopItem(context.Context, *PurchaseShopItemRequest) (*PurchaseShopItemResponse, error)
	// FreezeForOrder 拍卖挂单冻结资产(系统接口,仅后端内部直连):
	//
	//	卖单(SELL):把 quantity 个 item_config_id 从活跃背包移入托管(escrow),挂单期间不可被别处消耗;
	//	买单(BUY):把 quantity*unit_price 金币从活跃余额移入托管,出价期间锁定。
	//
	// 幂等键 = order_id(挂单雪花),同一挂单重复冻结只生效一次;资产不足 → ERR_INVENTORY_INSUFFICIENT。
	// 与 SettleAuctionMatch / ReleaseEscrow 配套:成交从 escrow 消费、撤单 / 过期从 escrow 退还。
	// 不在 Envoy 暴露;带玩家 JWT 的客户端调用一律拒绝(同 GrantItems)。
	FreezeForOrder(context.Context, *FreezeForOrderRequest) (*FreezeForOrderResponse, error)
	// EnsureAuctionEscrow 修复旧版本拍卖订单的托管缺口(系统接口,仅后端内部直连):
	//
	//	已有 active escrow 时严格核对方向、物品与剩余可结算资产,满足要求即幂等成功;
	//	escrow 缺失时从玩家活跃资产原子补冻 remaining_quantity 并创建 escrow。
	//
	// closed / 订单参数冲突会明确拒绝,绝不把唯一键冲突直接当成功。
	// 该 RPC 只供 auction 持久补偿器调用,不在 Envoy 暴露;带玩家 JWT 的调用一律拒绝。
	EnsureAuctionEscrow(context.Context, *EnsureAuctionEscrowRequest) (*EnsureAuctionEscrowResponse, error)
	// SettleAuctionMatch 原子结算一笔拍卖成交(系统接口,仅后端内部直连):
	//
	//	同一 MySQL 本地事务里从双方 escrow 消费完成资产对转 ——
	//	  卖家:从卖单 escrow 消费 quantity 个 item_config_id 交付买家,卖家加 quantity*unit_price 金币;
	//	  买家:从买单 escrow 消费 quantity*unit_price 金币付给卖家,买家加 quantity 个 item_config_id。
	//
	// 因双方资产已在 FreezeForOrder 阶段冻结,成交不会因余额不足失败。
	// 幂等键 = match_id(雪花),同一成交重复结算只生效一次(不变量 §9.2 / §9.7)。
	// 不在 Envoy 暴露;带玩家 JWT 的客户端调用一律拒绝(同 GrantItems)。
	SettleAuctionMatch(context.Context, *SettleAuctionMatchRequest) (*SettleAuctionMatchResponse, error)
	// SettlePlayerTrade 原子结算一笔玩家间点对点交易(系统接口,仅后端内部直连):
	//
	//	与拍卖不同,P2P 交易无 escrow 预冻,直接从双方活跃背包 / 余额在同一 MySQL 本地事务里对转 ——
	//	  卖家:手 seller_items 给买家,收 buyer_items + price 金币;
	//	  买家:手 buyer_items + price 金币给卖家,收 seller_items。
	//	任一方道具 / 金币不足 → ERR_INVENTORY_INSUFFICIENT,整笔回滚。
	//
	// 幂等键 = order_id(雪花),同一订单重复结算只生效一次(不变量 §9.7)。
	// 不在 Envoy 暴露;带玩家 JWT 的客户端调用一律拒绝(同 GrantItems)。
	SettlePlayerTrade(context.Context, *SettlePlayerTradeRequest) (*SettlePlayerTradeResponse, error)
	// ReleaseEscrow 拍卖挂单托管退还(系统接口,仅后端内部直连):
	//
	//	撤单 / 过期 / 完全成交后把某挂单 escrow 的残余资产退回玩家活跃余额并关闭托管。
	//	卖单残余 = 未成交道具;买单残余 = 未成交金币 + 成交价优于出价的价差返还。
	//
	// 幂等键 = order_id,重复退还只生效一次(escrow status=closed 后再调为 no-op)。
	// 不在 Envoy 暴露;带玩家 JWT 的客户端调用一律拒绝(同 GrantItems)。
	ReleaseEscrow(context.Context, *ReleaseEscrowRequest) (*ReleaseEscrowResponse, error)
	// EscrowOutInstances 邮件 transfer 托管扣出(系统接口,仅后端内部直连)。
	// 幂等键 = escrow_key(inventory_ledger uk,指纹含 instance_ids+to_player);
	// 实例不存在/非源玩家持有 → ERR_INVENTORY_ITEM_NOT_FOUND;绑定实例 → ERR_INVENTORY_INSTANCE_BOUND。
	// 不在 Envoy 暴露;带玩家 JWT 的客户端调用一律拒绝(同 GrantItems)。
	EscrowOutInstances(context.Context, *EscrowOutInstancesRequest) (*EscrowOutInstancesResponse, error)
	// ClaimTransferInstances 领取托管实例(mail ClaimMail 专用;系统接口,仅后端内部直连)。
	// 幂等键 = idempotency_key(mail 侧 mail_xfer:{mail}:{player});重放命中直接成功。
	// 托管行缺失 / to_player 不符 / config 漂移 → ERR_INVENTORY_ITEM_NOT_FOUND(整批拒,
	// 邮件保持未领取);领取人实例背包满 → ERR_INVENTORY_CAPACITY_FULL(重领可重试)。
	ClaimTransferInstances(context.Context, *ClaimTransferInstancesRequest) (*ClaimTransferInstancesResponse, error)
	// ReleaseTransferEscrow 托管释放回源玩家(发信 saga 失败补偿;系统接口,仅后端内部直连)。
	// 幂等由托管行存在性承担:行已被领取/已释放 → no-op 成功(资产只落一处)。
	// 释放不设容量闸(资产归还优先):无空闲格时以未分配格(slot NULL)入包。
	ReleaseTransferEscrow(context.Context, *ReleaseTransferEscrowRequest) (*ReleaseTransferEscrowResponse, error)
	// ConsumeTransferEscrow 消托管行不物化(bag phase 2 DS 领取链;mail.MarkMailClaimed 调):
	// transfer 附件已经 bag journal 原样入包(bag 域),经济域托管行只删不再物化,
	// 防"bag 域已入 + 托管行残留被释放/领取"造成实例双持。行必须 destined to 该玩家;
	// 行缺失 = 已消费,no-op 幂等。系统接口,仅后端内部直连。
	ConsumeTransferEscrow(context.Context, *ConsumeTransferEscrowRequest) (*ConsumeTransferEscrowResponse, error)
	// CheckItemsOwned 批量查询玩家是否持有指定配置道具(系统接口,仅后端内部直连)。
	//
	// 唯一用途:player.SetEquipment 的**拥有权**校验——出战装备预设会被 GetLoadout 转成
	// Battle DS 的初始 GameplayEffect,不校验拥有权等于客户端可以给自己配任意装备。
	// 「持有」= 可堆叠计数 > 0 或存在该配置的装备实例,两条路任一成立即算持有。
	//
	// 为什么不复用 GetInventory:后者是客户端 RPC,以 Envoy 注入的 JWT 身份为准,
	// 后端内部直连(callerID==0)会被判 ERR_UNAUTHORIZED,player 服务调不通。
	// 本 RPC 反过来只认内部直连,带玩家 JWT 一律拒(与 GrantItems 同口径),且不在 Envoy 暴露。
	//
	// 只回「请求集合中确实持有的子集」,不回数量、不回实例 id,避免把背包细节外溢到其它域。
	CheckItemsOwned(context.Context, *CheckItemsOwnedRequest) (*CheckItemsOwnedResponse, error)
	// CheckInstancesOwned 精确校验唯一实例归属(系统接口,仅后端内部直连)。
	// 每项同时携 instance_id + item_config_id；只有两者都与该玩家当前实例行一致才返回。
	// 旧 CheckItemsOwned 保留兼容，新的实例化装备预设应使用本接口避免同配置多实例选错词条。
	CheckInstancesOwned(context.Context, *CheckInstancesOwnedRequest) (*CheckInstancesOwnedResponse, error)
}

// UnimplementedInventoryServiceServer should be embedded to have
// forward compatible implementations.
//
// NOTE: this should be embedded by value instead of pointer to avoid a nil
// pointer dereference when methods are called.
type UnimplementedInventoryServiceServer struct{}

